class QTimer(QObject):
    timeout = pyqtSignal()

    def __init__(self, parent=None, **kw):
        QObject.__init__(self, parent, **kw)
        self._interval = 0
        self._single = False
        self._tid = None
        self._active = False

    def setInterval(self, ms):
        self._interval = int(ms)

    def interval(self):
        return self._interval

    def setSingleShot(self, b):
        self._single = bool(b)

    def isSingleShot(self):
        return self._single

    def setTimerType(self, t):
        pass

    def start(self, ms=None):
        if ms is not None:
            self._interval = int(ms)
        self.stop()
        self._active = True
        self._tid = _g.add_timer(self._interval, self._fire)

    def _fire(self):
        if not self._active:
            return
        if self._single:
            self._active = False
        else:
            self._tid = _g.add_timer(max(1, self._interval), self._fire)
        self.timeout.emit()

    def stop(self):
        self._active = False
        if self._tid:
            _g.cancel_timer(self._tid)
            self._tid = None

    def isActive(self):
        return self._active

    def remainingTime(self):
        return self._interval if self._active else -1

    @staticmethod
    def singleShot(ms, *args):
        func = args[-1]
        if isinstance(func, _BoundSignal):
            func = func.emit
        _g.add_timer(int(ms), func)


