def _qt_fmt(d, fmt):
    rep = [("yyyy", "%Y"), ("yy", "%y"), ("MMMM", "%B"), ("MMM", "%b"), ("MM", "%m"), ("dddd", "%A"),
           ("ddd", "%a"), ("dd", "%d"), ("HH", "%H"), ("hh", "%H"), ("mm", "%M"), ("ss", "%S"), ("AP", "%p"),
           ("ap", "%p")]
    out = str(fmt)
    for a, b in rep:
        out = out.replace(a, b)
    try:
        return d.strftime(out)
    except Exception:
        return str(d)


