class QTextEdit(QFrame):
    _kind = "TextEdit"
    textChanged = pyqtSignal()
    cursorPositionChanged = pyqtSignal()
    NoWrap, WidgetWidth = 0, 1
    LineWrapMode = _enum("LineWrapMode", NoWrap=0, WidgetWidth=1)

    def __init__(self, *args, **kw):
        text, parent = "", None
        for a in args:
            if isinstance(a, str):
                text = a
            elif isinstance(a, QWidget):
                parent = a
        self._text = text
        self._html = None
        QFrame.__init__(self, parent, **kw)

    def _init_opts(self):
        return {"text": self._text}

    def toPlainText(self):
        return self._text

    def setPlainText(self, t):
        self._text = str(t)
        self._html = None
        self._cfg(text=self._text, html=None)
        self.textChanged.emit()

    def setText(self, t):
        t = str(t)
        if "<" in t and ">" in t:
            self.setHtml(t)
        else:
            self.setPlainText(t)

    def setHtml(self, h):
        import re
        self._html = str(h)
        self._text = re.sub(r"<[^>]+>", "", self._html)
        self._cfg(html=self._html)
        self.textChanged.emit()

    def toHtml(self):
        return self._html or self._text

    def setMarkdown(self, m):
        self.setPlainText(m)

    def toMarkdown(self):
        return self._text

    def append(self, t):
        t = str(t)
        if self._html is not None:
            self._html += "<br>" + t
            self._text += "\n" + t
            self._cfg(html=self._html, scroll=True)
        else:
            self._text = (self._text + "\n" + t) if self._text else t
