class QAction(QObject):
    triggered = pyqtSignal(bool)
    toggled = pyqtSignal(bool)
    hovered = pyqtSignal()

    def __init__(self, *args, **kw):
        text, parent, icon = "", None, None
        for a in args:
            if isinstance(a, str):
                text = a
            elif isinstance(a, QIcon):
                icon = a
            elif isinstance(a, QObject):
                parent = a
        self._text = text
        self._checkable = False
        self._checked = False
        self._enabled = True
        self._shortcut = ""
        self._data = None
        self._sep = False
        self._menu = None
        self._aid = _g.new_id("act")
        QObject.__init__(self, parent, **kw)
        _g.register(self._aid, self)

    def text(self):
        return self._text

    def setText(self, t):
        self._text = str(t)
        self._changed()

    def setCheckable(self, b):
        self._checkable = bool(b)
        self._changed()

    def isCheckable(self):
        return self._checkable

    def setChecked(self, b):
        if bool(b) != self._checked:
            self._checked = bool(b)
            self.toggled.emit(self._checked)
            self._changed()

    def isChecked(self):
        return self._checked

    def setEnabled(self, b):
        self._enabled = bool(b)
        self._changed()

    def isEnabled(self):
        return self._enabled

    def setShortcut(self, s):
        self._shortcut = s.toString() if isinstance(s, QKeySequence) else str(s)
        self._changed()

    def setShortcuts(self, s):
        pass

    def setStatusTip(self, t):
        pass

    def setToolTip(self, t):
        pass

    def setIcon(self, i):
        pass

    def setData(self, d):
        self._data = d

    def data(self):
        return self._data

    def setSeparator(self, b):
        self._sep = bool(b)

    def setMenu(self, m):
        self._menu = m

    def menu(self):
        return self._menu

    def setVisible(self, b):
        pass

    def setShortcutContext(self, c):
        pass

    def trigger(self):
        if not self._enabled:
            return
        if self._checkable:
            self.setChecked(not self._checked)
        self.triggered.emit(self._checked)

    def _changed(self):
        for m in _MENUS:
            if self in m._actions:
                _g.mark_dirty(m)

    def _spec(self):
        if self._sep:
            return {"sep": True}
        d = {"id": self._aid, "text": self._text.replace("&", ""), "enabled": self._enabled,
             "checkable": self._checkable, "checked": self._checked, "shortcut": self._shortcut}
        if self._menu is not None:
            d["sub"] = [a._spec() for a in self._menu._actions]
        return d

    def _pyide_event(self, ev):
        self.trigger()


class QActionGroup(QObject):
    triggered = pyqtSignal(object)

    def __init__(self, parent=None):
        QObject.__init__(self, parent)
        self._acts = []

    def addAction(self, a):
        self._acts.append(a)
        a.triggered.connect(lambda *x, a=a: self._on(a))
        return a

    def _on(self, a):
        for o in self._acts:
            if o is not a and o._checked:
                o._checked = False
                o._changed()
        if not a._checked:
            a._checked = True
            a._changed()
        self.triggered.emit(a)

    def setExclusive(self, b):
        pass

    def checkedAction(self):
        for a in self._acts:
            if a._checked:
                return a
        return None


