class QMenu(QWidget):
    _kind = "Menu"
    triggered = pyqtSignal(object)
    aboutToShow = pyqtSignal()

    def __init__(self, *args, **kw):
        title, parent = "", None
        for a in args:
            if isinstance(a, str):
                title = a
            elif isinstance(a, QWidget):
                parent = a
        self._mtitle = title
        self._actions = []
        QWidget.__init__(self, parent, **kw)
        _MENUS.append(self)

    def title(self):
        return self._mtitle

    def setTitle(self, t):
        self._mtitle = str(t)
        _g.mark_dirty(self)

    def addAction(self, *args, **kw):
        if args and isinstance(args[0], QAction):
            act = args[0]
        else:
            text = next((a for a in args if isinstance(a, str)), "")
            act = QAction(text, self)
            for a in args:
                if callable(a) and not isinstance(a, (str, QIcon)):
                    act.triggered.connect(a)
                elif isinstance(a, (QKeySequence,)):
                    act.setShortcut(a)
            if "triggered" in kw:
                act.triggered.connect(kw["triggered"])
        act.triggered.connect(lambda *x, act=act: self.triggered.emit(act))
        self._actions.append(act)
        _g.mark_dirty(self)
        return act

    def addActions(self, acts):
        for a in acts:
            self.addAction(a)

    def addMenu(self, m):
        if isinstance(m, str):
            m = QMenu(m, self)
        act = QAction(m._mtitle, self)
        act._menu = m
        self._actions.append(act)
        _g.mark_dirty(self)
        return m

    def addSeparator(self):
        a = QAction("", self)
        a._sep = True
        self._actions.append(a)
        _g.mark_dirty(self)
        return a

    def clear(self):
        self._actions = []
        _g.mark_dirty(self)

    def actions(self):
        return list(self._actions)

    def menuAction(self):
        a = QAction(self._mtitle)
        a._menu = self
        return a

    def _pyide_sync(self):
        _g.op("qt_menu", self._id, self._mtitle.replace("&", ""), [a._spec() for a in self._actions])
        for b in _MENUBARS:
            if self in b._menus:
                _g.mark_dirty(b)

    def exec(self, pos=None, *a):
        self.aboutToShow.emit()
        p = pos or QPoint(0, 0)
        _g.flush()
        res = _g.sync_call("menu", {"items": [x._spec() for x in self._actions], "x": p.x(), "y": p.y()})
        if res:
            obj = _g._S.objects.get(res)
            if isinstance(obj, QAction):
                obj.trigger()
                return obj
        return None

    exec_ = popup = exec


