class IntVar(Variable):
    _default = 0

    def _coerce(self, v):
        if isinstance(v, bool):
            return int(v)
        if isinstance(v, str):
            v = v.strip()
            if v == "":
                return 0
            return int(float(v))
        return int(v)

    def get(self):
        v = self._value
        try:
            return self._coerce(v)
        except (TypeError, ValueError):
            raise TclError('expected integer but got "%s"' % v)


class DoubleVar(Variable):
    _default = 0.0

    def _coerce(self, v):
        if isinstance(v, str) and v.strip() == "":
