        pat = _parse_sequence(sequence)
        if not add:
            lst[:] = [b for b in lst if b[0] != pat]
        lst.append((pat, func, sequence))
        types = set()
        for bl in self._item_bindings.values():
            for (typ, d, mods), f, s in bl:
                js = _JS_TYPES.get(typ)
                if js:
