class Font:
    def __init__(self, root=None, font=None, name=None, exists=False, **options):
        spec = {"family": "TkDefaultFont", "size": 13, "weight": "normal", "slant": "roman",
                "underline": 0, "overstrike": 0}
        if name in _DEFAULTS:
            spec.update(_DEFAULTS[name])
