        old = tuple(cur)
        for s in statespec:
            if s.startswith("!"):
                cur.discard(s[1:])
            else:
                cur.add(s)
        self._states = cur
        if "disabled" in cur:
            self._opts["state"] = "disabled"
        elif self._opts.get("state") == "disabled":
            self._opts["state"] = "normal"
        if "readonly" in cur:
            self._opts["state"] = "readonly"
