            self._current = 0
        _g.mark_dirty(self)

    def insert(self, pos, child, **kw):
        kw = {_norm_key(k): v for k, v in kw.items()}
        child._manager = "notebook"
        self._tabs.insert(self._find(pos), (child, kw))
        if self._current is None:
            self._current = 0
        _g.mark_dirty(self)

    def forget(self, tab_id):
        i = self._find(tab_id)
        w, _ = self._tabs.pop(i)
        w._manager = None
        _g.op("forget", w._w)
        if not self._tabs:
            self._current = None
        elif self._current >= len(self._tabs):
            self._current = len(self._tabs) - 1
        _g.mark_dirty(self)

    def hide(self, tab_id):
        i = self._find(tab_id)
        self._tabs[i][1]["state"] = "hidden"
        _g.mark_dirty(self)

    def select(self, tab_id=None):
        if tab_id is None:
            return self._tabs[self._current][0]._w if self._current is not None else ""
        i = self._find(tab_id)
        if i != self._current:
            self._current = i
            _g.mark_dirty(self)
            self._fire_event("Virtual", {"name": "<<NotebookTabChanged>>"})
        return None

